import{_ as e,o as t,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第二次全体会议公报","description":"","frontmatter":{"prev":{"text":"陈云在党的十二届二中全会上的讲话","link":"./陈云在党的十二届二中全会上的讲话"},"next":{"text":"中共中央整党工作指导委员会名单","link":"./中共中央整党工作指导委员会名单"}},"headers":[],"relativePath":"12/2/中国共产党第十二届中央委员会第二次全体会议公报.md","filePath":"12/2/中国共产党第十二届中央委员会第二次全体会议公报.md"}'),r={name:"12/2/中国共产党第十二届中央委员会第二次全体会议公报.md"};function n(o,_,s,i,c,l){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="中国共产党第十二届中央委员会第二次全体会议公报" tabindex="-1">中国共产党第十二届中央委员会第二次全体会议公报 <a class="header-anchor" href="#中国共产党第十二届中央委员会第二次全体会议公报" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第二次全体会议公报&quot;">​</a></h1><p><em>（1983年10月12日）</em></p><p>  中国共产党第十二届中央委员会第二次全体会议，1983年10月11、12日在北京举行。在此之前，举行了预备会议。</p><p>  中央政治局常委胡耀邦、叶剑英、邓小平、赵紫阳、李先念、陈云出席并主持会议。到会的中央委员201人，中央候补委员136人。中央顾问委员会委员150人，中央纪律检查委员会委员124人，中央机关和地方党委的负责同志11人，列席了会议。</p><p>  会议经过认真热烈的讨论，一致通过了《中共中央关于整党的决定》。这个决定，体现了党的十二大的精神，明确规定了这次整党的基本方针、基本任务、基本政策和基本方法。全会认为，这个决定的贯彻执行，必将保证整党工作正确地顺利地进行。</p><p>  为了保证整党工作的日常领导，这次全会经过充分酝酿，选举产生了中央整党工作指导委员会。</p><p>  在这次全会上，邓小平同志、陈云同志就整党问题分别作了重要讲话。邓小平同志在讲话中，还提出了加强思想战线工作的问题。全会决定中央于今冬明春召开会议，专门讨论这个问题，并作出相应的决定。</p><p>  全会依照党章规定，决定递补中央候补委员杨泰芳、郎大忠（傣族）为中央委员。</p><p>  全会决定增补魏文伯、奎璧（蒙古族）、张苏、杜星垣、贾庭三为中央顾问委员会委员，以后提请下届党的全国代表大会追认。</p><p>  全会号召全体党员，认真学习《中共中央关于整党的决定》，积极参加整党。全会相信，经过各级党组织和广大党员的共同努力，我们一定能够胜利地完成这次整党的伟大任务，一定能够实现党风的根本好转，一定能够把我国社会主义物质文明和精神文明的建设推向前进。</p>',10)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
